import{_ as h,C as e,o as d,c as u,j as i,a as l,E as n,a3 as o}from"./chunks/framework.D4-ViStF.js";const y=JSON.parse('{"title":"说卦传","description":"讲八卦作法、卦德、取象与方位的传——从三才六画到先后天秩序，建立理解卦象语言的入口。","frontmatter":{"title":"说卦传","description":"讲八卦作法、卦德、取象与方位的传——从三才六画到先后天秩序，建立理解卦象语言的入口。","category":"guide","aliases":["说卦传","说卦","shuo gua zhuan"],"source":["《周易·说卦传》"]},"headers":[],"relativePath":"yijing/shi-yi/shuo-gua-zhuan.md","filePath":"yijing/shi-yi/shuo-gua-zhuan.md","lastUpdated":1788140575000}'),p={name:"yijing/shi-yi/shuo-gua-zhuan.md"};function c(m,a,g,b,q,f){const t=e("DaoReadingPrelude"),r=e("DaoTextReading"),s=e("DaoKeywordCards");return d(),u("div",null,[a[0]||(a[0]=i("h1",{id:"说卦传",tabindex:"-1"},[l("说卦传 "),i("a",{class:"header-anchor",href:"#说卦传","aria-label":'Permalink to "说卦传"'},"​")],-1)),n(t,{title:"先会其意，再进入万象",summary:"《说卦传》是十翼中专门展开八卦系统的一篇：它说明圣人如何作《易》，天地人三才如何成为六画，八卦如何对应自然、身体、亲属、动物与器物，也呈现先天的对待和后天的流行。它不是一张必须死背的对应表，而是一套从意入象、由象观变的阅读方法。",points:[{label:"先明根",text:"先读圣人作易的步骤，以及阴阳、柔刚、仁义的三才结构。"},{label:"再识象",text:"掌握八卦最核心的卦德：健、顺、动、入、陷、丽、止、说。"},{label:"后会通",text:"再看先天对待、后天流行和广取象，不把象例误当成穷尽。"}],hint:"取象的关键不是遇到任何事都机械查表，而是先问：此刻我取的是哪一种意？同一事物因所取之意不同，可能显出不同的卦象。"}),a[1]||(a[1]=o('<h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>《说卦传》是《易传》中集中解释八卦的篇章。它从圣人作《易》的方法讲起，说明三才、六画、先天方位、后天方位、八卦卦德与广泛取象。</p><p>「说卦」不是只给八卦配上几个名称，而是把乾、坤、震、巽、坎、离、艮、兑从卦画展开为一套可以观察天地、身体、人事与器物的象的体系。</p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><ul><li>六十四卦都是上下两个经卦的组合。先明八卦之意，才有可能读懂复合卦的结构。</li><li>它同时保存「对待」与「流行」两种视角：先天看相对位置，后天看万物随时令展开。</li><li>「近取诸身，远取诸物」说明取象始于真实经验，不是任意联想。</li><li>它提供的是示例性的象库。象有千万，学习重点在会其意，再把这个意应用到当前情境。</li></ul><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先读前七节，理解作易、三才、方位与八卦功能；不要一开始就背长串取象。</li><li>再记八卦八德：乾健、坤顺、震动、巽入、坎陷、离丽、艮止、兑说（说通悦）。</li><li>看到动物、身体和器物取象时，先问它体现的是卦德、卦形、功能还是关系，不急着只查字典。</li><li>先天与后天不必争哪个唯一根本：一个偏向空间对待，一个偏向时间流行，知道各自何时有用即可。</li><li>遇到版本差异或后世校订，保留经文、注疏和个人取象之间的层次，不把一种解释直接当作唯一结论。</li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>作易六步</strong>：幽赞神明而生蓍，参天两地而倚数，观阴阳而立卦，发挥刚柔而生爻，和顺道德而理义，穷理尽性以至于命。</li><li><strong>三才六画</strong>：天道阴阳，地道柔刚，人道仁义；兼三才而两之，故六画成卦，六位成章。</li><li><strong>先天八卦</strong>：天地定位，山泽通气，雷风相薄，水火不相射，八卦相错，重在对待与结构。</li><li><strong>后天八卦</strong>：帝出乎震，齐乎巽，相见乎离，致役乎坤，说言乎兑，战乎乾，劳乎坎，成言乎艮，重在流行与时序。</li><li><strong>八卦功能</strong>：雷动、风散、雨润、日烜、艮止、兑说、乾君、坤藏。</li><li><strong>八卦卦德</strong>：健、顺、动、入、陷、丽、止、说，是最短的取象入口。</li><li><strong>近取远取</strong>：乾首、坤腹、震足、巽股、坎耳、离目、艮手、兑口；乾马、坤牛、震龙、巽鸡、坎豕、离雉、艮狗、兑羊。</li><li><strong>广取象</strong>：各卦从卦形、卦德、自然、身体、器物与关系不断展开，重在由意会象而非机械穷举。</li></ul><h2 id="与六十四卦的联动" tabindex="-1">与六十四卦的联动 <a class="header-anchor" href="#与六十四卦的联动" aria-label="Permalink to &quot;与六十四卦的联动&quot;">​</a></h2><ul><li>读任意卦页时，先拆出上下经卦，再分别看它们的卦德和基本象，例如屯为上坎、下震，既有险陷也有发动。</li><li>先天「八卦相错」适合观察对待关系；后天「帝出乎震」适合观察时序、方位与万物流行。</li><li>「数往者顺，知来者逆」可与卜筮阅读联动，但不能把取象变成脱离现实的任意预测。</li><li>可回看<a href="/Dao/topics/traditional-wisdom/01-philosophy/03-four-symbols"><code>四象论</code></a>，区分《易》学中由阴阳分化的四象与天文方位中的四方四神。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>',12)),n(r,{colophon:"三才六画 · 先天对待 · 后天流行 · 会意取象",tone:"ink",sections:[{id:"duan-01",sentences:[["昔者圣人之作《易》也，幽赞于神明而生蓍，参天两地而倚数，观变于阴阳而立卦，发挥于刚柔而生爻，和顺于道德而理于义，穷理尽性以至于命。"],["昔者圣人之作《易》也，将以顺性命之理。是以立天之道曰阴与阳，立地之道曰柔与刚，立人之道曰仁与义。"],["兼三才而两之，故《易》六画而成卦。分阴分阳，迭用柔刚，故《易》六位而成章。"]]},{id:"duan-02",sentences:[["天地定位，山泽通气，雷风相薄，水火不相射，八卦相错。"],["数往者顺，知来者逆，是故《易》逆数也。"],["雷以动之，风以散之，雨以润之，日以烜之，艮以止之，兑以说之，乾以君之，坤以藏之。"]]},{id:"duan-03",sentences:[["帝出乎震，齐乎巽，相见乎离，致役乎坤，说言乎兑，战乎乾，劳乎坎，成言乎艮。"],["万物出乎震，震东方也。齐乎巽，巽东南也；齐也者，言万物之絜齐也。"],["离也者，明也，万物皆相见，南方之卦也；圣人南面而听天下，向明而治，盖取诸此也。"],["坤也者，地也，万物皆致养焉，故曰致役乎坤。兑，正秋也，万物之所说也，故曰说言乎兑。"],["战乎乾，乾西北之卦也，言阴阳相薄也。坎者水也，正北方之卦也，劳卦也，万物之所归也，故曰劳乎坎。"],["艮，东北之卦也，万物之所成终而成始也，故曰成言乎艮。"]]},{id:"duan-04",sentences:[["神也者，妙万物而为言者也。动万物者莫疾乎雷，挠万物者莫疾乎风，躁万物者莫乎火，说万物者莫说乎泽，润万物者莫润乎水，终万物始万物者莫盛乎艮。"],["故水火相逮，雷风不相悖，山泽通气，然后能变化，既成万物也。"],["乾，健也；坤，顺也；震，动也；巽，入也；坎，陷也；离，丽也；艮，止也；兑，说也。"]]},{id:"duan-05",sentences:[["乾为马，坤为牛，震为龙，巽为鸡，坎为豕，离为雉，艮为狗，兑为羊。"],["乾为首，坤为腹，震为足，巽为股，坎为耳，离为目，艮为手，兑为口。"],["乾，天也，故称乎父；坤，地也，故称乎母。震一索而得男，故谓之长男；巽一索而得女，故谓之长女。"],["坎再索而得男，故谓之中男；离再索而得女，故谓之中女；艮三索而得男，故谓之少男；兑三索而得女，故谓之少女。"]]},{id:"duan-06",sentences:[["乾为天，为圆，为君，为父，为玉，为金，为寒，为冰，为大赤，为良马，为老马，为瘠马，为驳马，为木果。"],["坤为地，为母，为布，为釜，为吝啬，为均，为子母牛，为大舆，为文，为众，为柄，其于地也为黑。"],["震为雷，为龙，为玄黄，为旉，为大途，为长子，为决躁，为苍筤竹，为萑苇；其于马也为善鸣，为馵足，为作足，为的颡；其于稼也为反生，其究为健，为蕃鲜。"],["巽为木，为风，为长女，为绳直，为工，为白，为长，为高，为进退，为不果，为臭；其于人也为寡发，为广颡，为多白眼，为近利市三倍，其究为躁卦。"]]},{id:"duan-07",sentences:[["坎为水，为沟渎，为隐伏，为矫輮，为弓轮；其于人也为加忧，为心病，为耳痛，为血卦，为赤；其于马也为美脊，为亟心，为下首，为薄蹄，为曳；其于舆也为多眚，为通，为月，为盗；其于木也为坚多心。"],["离为火，为日，为电，为中女，为甲胄，为戈兵；其于人也为大腹，为乾卦，为鳖，为蟹，为蠃，为蚌，为龟；其于木也为科上槁。"],["艮为山，为径路，为小石，为门阙，为果蓏，为阍寺，为指，为狗，为鼠，为黔喙之属；其于木也为坚多节。"],["兑为泽，为少女，为巫，为口舌，为毁折，为附决；其于地也为刚卤，为妾，为羊。"]]}],"aria-label":"说卦传原文"}),a[2]||(a[2]=i("blockquote",null,[i("p",null,"注：本页据通行本整理。「艮为手」与后文「艮为指」等文字，在历代传本、注疏和后世易学中有不同讨论；「离为中女」按上下文及通行本校正。取象解释也不等同于经文逐项给出唯一推导。")],-1)),a[3]||(a[3]=i("h2",{id:"【原典层】字词释义",tabindex:"-1"},[l("【原典层】字词释义 "),i("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),n(s,{items:[{term:"幽赞",pinyin:["yōu","zàn"],meaning:"在幽微处辅助、赞襄神明。放在作《易》的语境中，指对不可尽见的变化保持敬畏，并由此进入蓍筮与象数。"},{term:"三才",pinyin:["sān","cái"],meaning:"天、地、人。天道为阴阳，地道为柔刚，人道为仁义；三才各有两面，重之而成六画。"},{term:"相错",pinyin:["xiāng","cuò"],meaning:"彼此交错、相对配置。先天八卦以乾坤、山泽、雷风、水火等对待关系呈现结构。"},{term:"逆数",pinyin:["nì","shǔ"],meaning:"由已见之象推知未至之事。「数往者顺，知来者逆」说明《易》包含由现在观未来的推演方向。"},{term:"絜齐",pinyin:["jié","qí"],meaning:"整齐、齐一。「齐乎巽」写万物在生长过程中逐渐整饬、成形，而非静止排列。"},{term:"说",pinyin:["tuō"],meaning:"在「兑以说之」「兑，说也」中通「悦」，指和悦、喜悦、使万物舒展。"},{term:"丽",pinyin:["lí"],meaning:"附丽、依附。「离，丽也」不是单指美丽，而是事物有所附着，因依托而明。"},{term:"一索",pinyin:["yī","suǒ"],meaning:"第一次求取、交感。乾坤为父母，三次交感分别生出长、中、少三男三女，是八卦亲属象的生成说明。"},{term:"取象",pinyin:["qǔ","xiàng"],meaning:"从卦德、卦形、功能、关系或经验中取其相似之意。象例不是穷举，关键是会通当前情境中的那个意。"},{term:"先天",pinyin:["xiān","tiān"],meaning:"在本页主要指天地定位、山泽通气等对待结构，偏重空间关系与阴阳相对。"},{term:"后天",pinyin:["hòu","tiān"],meaning:"在本页主要指帝出乎震、成言乎艮的流行次序，偏重时间、方位与万物生长收藏。"},{term:"成终成始",pinyin:["chéng","zhōng","chéng","shǐ"],meaning:"既完成一个周期，又开启下一个周期。「艮」处于后天方位的终始交界，提示结束与开始相接。"}]}),a[4]||(a[4]=o('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><blockquote><p>本节把原典与本次整理的心得分开呈现。涉及传本异文、麻衣校订和个人取象的部分，均保留为可讨论的解释层。</p></blockquote><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>《说卦传》先讲八卦如何被建立，再讲八卦如何进入天地、人身和万物。它一方面给出乾坤、震巽、坎离、艮兑的基本德性，另一方面不断扩展取象：八卦可以是自然现象，也可以是身体部位、动物、亲属、器物和社会功能。</p><p>因此，它不是在说「一个卦永远只对应一个东西」，而是在示范一种从意到象的思考：乾的核心是健，坤的核心是顺，离的核心是明与附丽，艮的核心是止；遇到具体事物时，再看它当前显出的哪一层意。</p><h3 id="理-先天与后天、意与象如何并列" tabindex="-1">理：先天与后天、意与象如何并列 <a class="header-anchor" href="#理-先天与后天、意与象如何并列" aria-label="Permalink to &quot;理：先天与后天、意与象如何并列&quot;">​</a></h3><ul><li>先天八卦讲对待，后天八卦讲流行；一个像结构的骨架，一个像时间里的气血，不必互相排斥。</li><li>取象有时依据卦德，有时依据卦形，有时依据功能、位置或关系；不强行寻找一个能解释全部象例的单一公式。</li><li>《说卦》列出的是重要示范，不可能穷尽所有象。理解卦意之后，才有在新情境中活用的空间。</li><li>经文、传本、注疏与个人直觉需要分层。能从卦形推出一个有说服力的取象，不等于这就是所有版本共同承认的原文结论。</li></ul><h3 id="用-今天怎么进入八卦取象" tabindex="-1">用：今天怎么进入八卦取象 <a class="header-anchor" href="#用-今天怎么进入八卦取象" aria-label="Permalink to &quot;用：今天怎么进入八卦取象&quot;">​</a></h3><p>遇到一个人、一件事或一个突然出现的事物，可以依次问：</p><ul><li>我第一眼真正感受到的是什么意：明、入、止、动、陷、健，还是顺？</li><li>这个意是从形状、颜色、功能、位置、关系还是时序中显出来的？</li><li>如果换一个参照物，取象是否会改变？我是在查表，还是确实看见了当前处境的结构？</li></ul><p>例如一丛绿叶中的一片红叶，若所取的是「在众中显现、明而附丽」，可以取离；重点不在把某种物件永远钉死为某卦，而在于当下起心动念所取的意是否清楚、是否与情境相应。</p><h2 id="【解读层】分段解读" tabindex="-1">【解读层】分段解读 <a class="header-anchor" href="#【解读层】分段解读" aria-label="Permalink to &quot;【解读层】分段解读&quot;">​</a></h2><h3 id="一、圣人作易-从理、性到命" tabindex="-1">一、圣人作易：从理、性到命 <a class="header-anchor" href="#一、圣人作易-从理、性到命" aria-label="Permalink to &quot;一、圣人作易：从理、性到命&quot;">​</a></h3><p>开篇的六个步骤，从蓍、数、卦、爻一路进入道德、义理和性命。这里的顺序不是把《易》变成纯占卜技术：数与卦提供可观察的结构，爻展示刚柔变化，最后还要回到道德、义理与人的生命位置。</p><p>「穷理尽性以至于命」可以作为全篇的远景：先理解事物的理，再体会自身的性，最后面对那些不能被简单控制、只能在实践中抵达的命。读《易》若只停在象数，不足以完成这条路径。</p><h3 id="二、三才六画-天、地、人不是三个孤立层次" tabindex="-1">二、三才六画：天、地、人不是三个孤立层次 <a class="header-anchor" href="#二、三才六画-天、地、人不是三个孤立层次" aria-label="Permalink to &quot;二、三才六画：天、地、人不是三个孤立层次&quot;">​</a></h3><p>天有阴阳，地有柔刚，人有仁义。六画并不是单纯的数量，而是三才各自展开两面之后形成的结构。由下而上读六爻时，可以同时观察地、人、天三个层次如何彼此作用。</p><p>这也说明《易》的象不只用于自然：人的选择、关系和责任，同样属于卦象可以照见的范围。人并非站在天地之外观看，而是变化结构中的一层。</p><h3 id="三、先天八卦-对待不是静止-而是相互成就" tabindex="-1">三、先天八卦：对待不是静止，而是相互成就 <a class="header-anchor" href="#三、先天八卦-对待不是静止-而是相互成就" aria-label="Permalink to &quot;三、先天八卦：对待不是静止，而是相互成就&quot;">​</a></h3><p>「天地定位，山泽通气，雷风相薄，水火不相射」列出四组关系。乾坤有上下，山泽有通气，雷风有激发，水火有相济；相对不等于互相消灭，差异反而构成变化的动力。</p><p>「数往者顺，知来者逆」常被用于说明从已然推未然的方向。应用时仍应先有现实的象与条件，再谈推演，不把「逆数」理解成脱离根据的猜测。</p><h3 id="四、后天八卦-万物沿着时序展开" tabindex="-1">四、后天八卦：万物沿着时序展开 <a class="header-anchor" href="#四、后天八卦-万物沿着时序展开" aria-label="Permalink to &quot;四、后天八卦：万物沿着时序展开&quot;">​</a></h3><p>「帝出乎震」写万物在东方发动；巽使之齐，离使之相见，坤使之受养，兑是秋日的喜悦，乾处阴阳相薄，坎使万物归藏，艮让一个周期成终并开启新的开始。</p><p>先天偏于「哪里与哪里相对」，后天偏于「事物如何在时间中流动」。你对先天、后天的取舍，可以由问题决定：要看结构，还是要看时序；要看骨架，还是要看运行。</p><h3 id="五、八卦之神-变化不是八个孤立动词" tabindex="-1">五、八卦之神：变化不是八个孤立动词 <a class="header-anchor" href="#五、八卦之神-变化不是八个孤立动词" aria-label="Permalink to &quot;五、八卦之神：变化不是八个孤立动词&quot;">​</a></h3><p>雷动、风散、雨润、日烜、山止、泽悦、乾君、坤藏，说明八卦既是名词，也是作用方式。八卦相互配合，水火、雷风、山泽彼此不悖，变化才能完成万物。</p><p>所以取象时不要只找一个静态对象。更有帮助的问题是：当前这个象正在动、散、润、明、止、悦、统摄还是收藏？它和其他力量如何配合？</p><h3 id="六、广取象-由意入象-不被对应表困住" tabindex="-1">六、广取象：由意入象，不被对应表困住 <a class="header-anchor" href="#六、广取象-由意入象-不被对应表困住" aria-label="Permalink to &quot;六、广取象：由意入象，不被对应表困住&quot;">​</a></h3><p>乾为马，因为马体现健行；坤为牛，因为牛体现顺载；震为龙，因为龙体现发动与变化；艮为狗，因为狗可以体现守门与止。身体、动物和器物的象例，都是在不同经验中呈现八卦之意。</p><p>你提出的「绿叶中的一片红叶取离」正好说明了这一点：不是因为红叶在表格里固定属于离，而是因为当前看见的是「众中显明、附丽而有光」的意。换一个情境，所取之意也可能不同。</p><h3 id="七、艮为手还是为鼻-把经文与校订放在一起读" tabindex="-1">七、艮为手还是为鼻：把经文与校订放在一起读 <a class="header-anchor" href="#七、艮为手还是为鼻-把经文与校订放在一起读" aria-label="Permalink to &quot;七、艮为手还是为鼻：把经文与校订放在一起读&quot;">​</a></h3><p>今本第十节有「艮为手」，后文又有「艮为指」；后世易学中有人据卦形、先天对待与卦德，提出艮为鼻、巽为手的校订或解释。这里至少存在三个层次：今本文字、后世校订，以及读者由卦形所作的推论。</p><p>你提出「艮一阳在上、两阴在下，像鼻梁与两个鼻孔；艮又有止、辨气之意」的判断，是一种从卦形和卦德会通的取象。它很有启发性，但页面保留讨论空间，不替传本和学术校勘作最终裁决。</p><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>我们面对世界时，往往先看到纷繁的对象，随后才慢慢发现它们背后有重复出现的关系和力量。《说卦传》做的，就是把这些关系整理成八种基本倾向：有的向前发动，有的向内进入，有的陷落，有的附着发明，有的停止，有的和悦，有的健行，有的承载收藏。</p><p>先天八卦像一张关系地图，告诉我们哪些力量彼此相对、彼此贯通；后天八卦像一条时间路径，告诉我们万物如何发生、整齐、显明、受养、收获、交战、归藏，再在新的起点完成循环。</p><p>真正使用八卦，不是拿着一张表格把所有事物硬塞进去，而是先看清当前情境中的主导之意：它是在生长还是收束，在显明还是隐藏，在进入还是止住；再用合适的象去表达和判断。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>这次整理留下三点阶段性理解：</p><ul><li><strong>先天与后天并列而重要</strong>：先天讲对待，后天讲流行；一个是结构，一个是运行，应用时知其然，也知其所以然，不必执着谁才是唯一根本。</li><li><strong>取象重意不重表</strong>：说卦列出的象是示例，不是穷举。梅花易数中的起心动念，重在当下是否会其意；可以从一片红叶看见离的明与丽，而不必被固定分类牵住。</li><li><strong>艮为鼻是一种有根据的会通</strong>：一阳在上、两阴在下，既有山形突出之象，也可以联想到鼻梁与鼻孔；但今本、校订和个人推论仍应分别标明。</li></ul><h2 id="延伸阅读-参考来源" tabindex="-1">延伸阅读 / 参考来源 <a class="header-anchor" href="#延伸阅读-参考来源" aria-label="Permalink to &quot;延伸阅读 / 参考来源&quot;">​</a></h2><ul><li>上一篇：<a href="/Dao/yijing/shi-yi/xu-gua-zhuan"><code>序卦传</code></a></li><li>十翼总览：<a href="/Dao/yijing/shi-yi/"><code>孔子十翼</code></a></li><li>六十四卦目录：<a href="/Dao/yijing/hexagrams/"><code>文王六十四卦</code></a></li><li>相关专题：<a href="/Dao/topics/traditional-wisdom/01-philosophy/03-four-symbols"><code>四象论</code></a></li><li>卜筮联动：<a href="/Dao/yijing/meihua-yishu/"><code>梅花易数</code></a></li><li>通行本《周易·说卦传》（王弼注、孔颖达疏系统）</li></ul>',42))])}const P=h(p,[["render",c]]);export{y as __pageData,P as default};
